// Package base64 implements gomplate's `base64` template-function namespace.
// Encode uses the standard RFC4648 §4 encoding; Decode and DecodeBytes accept
// both the standard and the URL-safe (RFC4648 §5) padded encodings. When
// both decodings fail, the URL-safe decoder's error is returned, matching the
// reference behaviour. Non-string arguments are coerced to strings: nil
// becomes "", byte slices their string content, and everything else uses
// fmt's %v semantics.
package base64

import (
	stdb64 "encoding/base64"
	"fmt"
)

// NS returns the namespace object whose methods are the `base64` template
// functions.
func NS() any {
	return &ns{}
}

type ns struct{}

func toString(in any) string {
	switch v := in.(type) {
	case nil:
		return ""
	case string:
		return v
	case []byte:
		return string(v)
	}
	return fmt.Sprintf("%v", in)
}

// Encode implements base64.Encode: standard (RFC4648 §4) encoding of the
// input, coerced to a string when necessary.
func (n *ns) Encode(in any) string {
	return stdb64.StdEncoding.EncodeToString([]byte(toString(in)))
}


