// Package conv implements gomplate's `conv` template-function namespace:
// conversions between strings, numbers, booleans, and a few assorted helpers
// (Default, Join, URL). String-to-number conversions are lenient: commas are
// stripped, integer strings are parsed base-prefix aware (0x, 0b, 0o,
// underscores), and float strings fall back to truncation for ToInt64.
package conv

import (
	"errors"
	"fmt"
	"math"
	"net/url"
	"reflect"
	"strconv"
	stdstrings "strings"
)

// NS returns the namespace object whose methods are the `conv` template
// functions.
func NS() any {
	return &ns{}
}

// Aliases returns the top-level template-function aliases for this namespace.
//
// Note: the docs list `bool` as the alias for conv.Bool, but the reference
// binary defines neither `bool` nor conv.Bool. Both are provided here anyway
// for doc compatibility.
func Aliases() map[string]any {
	n := NS().(*ns)
	return map[string]any{
		"bool":     n.Bool,
		"default":  n.Default,
		"join":     n.Join,
		"urlParse": n.URL,
	}
}

type ns struct{}

// Bool implements conv.Bool: converts a true-ish string to a boolean using
// strconv.ParseBool; unparseable input yields false.
func (n *ns) Bool(in string) bool {
	b, _ := strconv.ParseBool(in)
	return b
}

// Default implements conv.Default: returns def when in is "empty" (nil,
// false, numeric zero, empty string/array/slice/map, nil pointer-like).
func (n *ns) Default(def, in any) any {
	if empty(in) {
		return def
	}
	return in
}

func empty(in any) bool {
	if in == nil {
		return true
	}
	v := reflect.ValueOf(in)
	switch v.Kind() {
	case reflect.Bool:
		return !v.Bool()
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return v.Int() == 0
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return v.Uint() == 0
	case reflect.Float32, reflect.Float64:
		return v.Float() == 0
	case reflect.Complex64, reflect.Complex128:
		return v.Complex() == 0
	case reflect.String, reflect.Slice, reflect.Array, reflect.Map, reflect.Chan:
		return v.Len() == 0
	case reflect.Ptr, reflect.Interface, reflect.Func, reflect.UnsafePointer:
		return v.IsNil()
	}
	return false
}

// Join implements conv.Join: concatenates the elements of an array or slice,
// each stringified with ToString semantics, placing sep between elements.
func (n *ns) Join(in any, sep string) (string, error) {
	v := reflect.ValueOf(in)
	if !v.IsValid() || (v.Kind() != reflect.Slice && v.Kind() != reflect.Array) {
		return "", errors.New("input to Join must be an array: expected an array or slice, but got a reflect.Value")
	}
	elems := make([]string, v.Len())
	for i := 0; i < v.Len(); i++ {
		elems[i] = toString(v.Index(i).Interface())
	}
	return stdstrings.Join(elems, sep), nil
}

// URL implements conv.URL: parses the stringified input with url.Parse.
func (n *ns) URL(in any) (*url.URL, error) {
	return url.Parse(toString(in))
}

// ParseInt implements conv.ParseInt (strconv.ParseInt).
func (n *ns) ParseInt(in string, base, bitSize int) (int64, error) {
	return strconv.ParseInt(in, base, bitSize)
}

// ParseUint implements conv.ParseUint (strconv.ParseUint).
func (n *ns) ParseUint(in string, base, bitSize int) (uint64, error) {
	return strconv.ParseUint(in, base, bitSize)
}

// ParseFloat implements conv.ParseFloat (strconv.ParseFloat).
func (n *ns) ParseFloat(in string, bitSize int) (float64, error) {
	return strconv.ParseFloat(in, bitSize)
}

// Atoi implements conv.Atoi (strconv.Atoi).
func (n *ns) Atoi(in string) (int, error) {
	return strconv.Atoi(in)
}

// ToBool implements conv.ToBool. True values are: boolean true, the strings
// "t", "true", "yes" (any capitalization), and any input that converts to the
// number 1. Everything else is false.
func (n *ns) ToBool(in any) bool {
	return toBool(in)
}

// ToBools implements conv.ToBools: ToBool applied to each input.
func (n *ns) ToBools(in ...any) []bool {
	out := make([]bool, len(in))
	for i, v := range in {
		out[i] = toBool(v)
	}
	return out
}

func toBool(in any) bool {
	switch v := in.(type) {
	case bool:
		return v
	case string:
		switch stdstrings.ToLower(v) {
		case "t", "true", "yes":
			return true
		}
		if i, err := strconv.ParseInt(v, 0, 64); err == nil {
			return i == 1
		}
		if f, err := strconv.ParseFloat(v, 64); err == nil {
			return f == 1
		}
		return false
	}
	f, err := toFloat64(in)
	return err == nil && f == 1
}

// ToInt64 implements conv.ToInt64.
func (n *ns) ToInt64(in any) (int64, error) {
	return toInt64(in)
}

// ToInt implements conv.ToInt: ToInt64 narrowed to int. On 32-bit platforms
// out-of-range values yield -1 (CWE-190/CWE-681 protection).
func (n *ns) ToInt(in any) (int, error) {
	i64, err := toInt64(in)
	if err != nil {
		return 0, err
	}
	if strconv.IntSize == 32 && (i64 > math.MaxInt32 || i64 < math.MinInt32) {
		return -1, nil
	}
	return int(i64), nil
}

// ToInt64s implements conv.ToInt64s.
func (n *ns) ToInt64s(in ...any) ([]int64, error) {
	out := make([]int64, len(in))
	for i, v := range in {
		n, err := toInt64(v)
		if err != nil {
			return nil, err
		}
		out[i] = n
	}
	return out, nil
}

// ToInts implements conv.ToInts.
func (n *ns) ToInts(in ...any) ([]int, error) {
	out := make([]int, len(in))
	for i, v := range in {
		iv, err := n.ToInt(v)
		if err != nil {
			return nil, err
		}
		out[i] = iv
	}
	return out, nil
}

// ToFloat64 implements conv.ToFloat64.
func (n *ns) ToFloat64(in any) (float64, error) {
	return toFloat64(in)
}

// ToFloat64s implements conv.ToFloat64s.
func (n *ns) ToFloat64s(in ...any) ([]float64, error) {
	out := make([]float64, len(in))
	for i, v := range in {
		f, err := toFloat64(v)
		if err != nil {
			return nil, err
		}
		out[i] = f
	}
	return out, nil
}

// ToString implements conv.ToString: nil becomes "nil", everything else uses
// fmt's %v semantics.
func (n *ns) ToString(in any) string {
	return toString(in)
}

// ToStrings implements conv.ToStrings.
func (n *ns) ToStrings(in ...any) []string {
	out := make([]string, len(in))
	for i, v := range in {
		out[i] = toString(v)
	}
	return out
}

func toString(in any) string {
